  1073     // Check if we have enough space to create the NV Index
  1074     // In this implementation, the only resource limitation is the available NV
  1075     // space (and possibly RAM space.)  Other implementation may have other
  1076     // limitation on counter or on NV slots
  1077     if(!NvTestSpace(entrySize, TRUE, IsNvCounterIndex(publicArea->attributes)))
